// Turns src/design/tokens.json into everything that consumes it:
//   src/design/tokens.css      CSS custom properties (imported first by main.ts)
//   index.html                 the inline palette list between the tokens:palettes markers
//   docs/design/TOKENS.md      a reference table for people and agents
// `bun scripts/tokens.ts --check` fails when any generated file is out of date.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';

const ROOT = join(import.meta.dir, '..');
const tokens = JSON.parse(readFileSync(join(ROOT, 'src/design/tokens.json'), 'utf8'));
const check = process.argv.includes('--check');

type Tok = { $value: unknown; $description?: string; $type?: string };
const isTok = (x: any): x is Tok => x && typeof x === 'object' && '$value' in x;
const css = (t: Tok, type?: string) => {
  const v = t.$value;
  if (type === 'fontFamily' && Array.isArray(v)) return v.map((f) => (/\s/.test(f) && !/^(system-ui|sans-serif|monospace|ui-monospace)$/.test(f) ? `'${f}'` : f)).join(', ');
  if (type === 'cubicBezier' && Array.isArray(v)) return `cubic-bezier(${v.join(', ')})`;
  return String(v);
};

// group → CSS variable prefix (aliases keep the names the stylesheet already uses)
const groups: [string, string][] = [['font', ''], ['text', 'text-'], ['radius', 'radius-'], ['border', 'border-'], ['lift', 'lift-'], ['space', 'space-'], ['layout', ''], ['ease', ''], ['duration', 'dur-']];
const rows: { name: string; value: string; desc: string; group: string }[] = [];
const lines: string[] = [];
for (const [k, t] of Object.entries<any>(tokens.color)) {
  if (!isTok(t)) continue; // palettes are applied at runtime, not as :root variables
  lines.push(`  --${k}: ${css(t)};`);
  rows.push({ group: 'color', name: `--${k}`, value: String(t.$value), desc: t.$description ?? '' });
}
for (const [k, t] of Object.entries<any>(tokens.derived)) if (isTok(t)) { lines.push(`  --${k}: ${css(t)};`); rows.push({ group: 'derived', name: `--${k}`, value: String(t.$value), desc: t.$description ?? '' }); }
for (const [g, prefix] of groups) {
  const grp = tokens[g];
  const name = (k: string) => (g === 'ease' ? (k === 'out' ? '--ease' : '--spring') : g === 'font' && k === 'sans' ? '--sans' : `--${prefix}${k}`);
  for (const [k, t] of Object.entries<any>(grp)) {
    if (!isTok(t)) continue;
    const v = css(t, t.$type ?? grp.$type);
    lines.push(`  ${name(k)}: ${v};`);
    rows.push({ group: g, name: name(k), value: v, desc: t.$description ?? '' });
  }
}
lines.push('  --r: var(--radius-card); /* legacy alias */');

const tokensCss = `/* GENERATED by scripts/tokens.ts from src/design/tokens.json — do not edit by hand. */
:root {
${lines.join('\n')}
}
`;

// palettes → inline script in index.html
const pals = Object.values<any>(tokens.color.palette).filter((p) => p && p.bg);
const palJs = pals.map((p) => `          { name: '${p.name.$value}', bg: '${p.bg.$value}', fg: '${p.fg.$value}', card: '${p.card.$value}', a1: '${p.a1.$value}', a2: '${p.a2.$value}', a3: '${p.a3.$value}' }`).join(',\n');
const indexPath = join(ROOT, 'index.html');
const index = readFileSync(indexPath, 'utf8');
const START = '/* tokens:palettes:start (generated) */', END = '/* tokens:palettes:end */';
if (!index.includes(START)) throw new Error('index.html is missing the tokens:palettes markers');
const newIndex = index.replace(new RegExp(`${START.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')}[\\s\\S]*?${END.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')}`), `${START}\n        var P = [\n${palJs}\n        ];\n        ${END}`);

// docs
const md = [`# Design tokens`, '', `Generated from \`src/design/tokens.json\` by \`bun run tokens\`. Do not edit by hand.`, '',
  '## Palettes', '', '| Palette | bg | fg | card | a1 | a2 | a3 |', '|---|---|---|---|---|---|---|',
  ...pals.map((p) => `| ${p.name.$value} | \`${p.bg.$value}\` | \`${p.fg.$value}\` | \`${p.card.$value}\` | \`${p.a1.$value}\` | \`${p.a2.$value}\` | \`${p.a3.$value}\` |`),
  '', 'Runtime variables set by the active palette: `--bg --fg --card --a1 --a2 --a3`. Accents always carry `--ink` text.', '',
  ...[...new Set(rows.map((r) => r.group))].flatMap((g) => [`## ${g}`, '', '| Variable | Value | Use |', '|---|---|---|', ...rows.filter((r) => r.group === g).map((r) => `| \`${r.name}\` | \`${r.value}\` | ${r.desc} |`), ''])
].join('\n');

const outputs: [string, string][] = [[join(ROOT, 'src/design/tokens.css'), tokensCss], [indexPath, newIndex], [join(ROOT, 'docs/design/TOKENS.md'), md]];
let stale = 0;
for (const [file, body] of outputs) {
  let cur = '';
  try { cur = readFileSync(file, 'utf8'); } catch {}
  if (cur === body) continue;
  if (check) { stale++; console.error(`out of date: ${file.replace(ROOT + '/', '')} (run \`bun run tokens\`)`); continue; }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, body);
  console.log('wrote', file.replace(ROOT + '/', ''));
}
if (check && stale) process.exit(1);
if (check) console.log('tokens: generated files are up to date');
